import{_ as e,o as t,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2018-Jun-20 :: Ceph Testing Weekly","description":"","frontmatter":{"title":"2018-Jun-20 :: Ceph Testing Weekly","date":"2018-06-20T00:00:00.000Z","updated":"2018-06-21T00:00:00.000Z","tags":["Ceph","Telltale","OpenStack","Jenkins","测试框架","分布式存储","测试覆盖","智能调度"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-Jun-20_-_-_Ceph_Testing_Weekly.md","filePath":"posts/2018/2018-Jun-20_-_-_Ceph_Testing_Weekly.md","lastUpdated":1780459816000}'),_={name:"posts/2018/2018-Jun-20_-_-_Ceph_Testing_Weekly.md"};function p(n,l,s,T,o,r){return t(),i("div",null,[...l[0]||(l[0]=[a("<p>本次会议主要讨论了Ceph存储系统中Telltale测试框架的更新与改进。会议中涉及的关键细节包括：</p><ul><li>Telltale测试框架目前依赖于OpenStack基础设施，环境搭建复杂，维护成本高，且测试覆盖率有限。</li><li>讨论了使用OVH实例搭建测试环境，并利用Jenkins进行测试任务调度。</li><li>创建了特定测试套件，如smoke test和fault test，以验证Telltale的基本功能。</li><li>探索了更新Telltale测试套件，提高测试覆盖率，并考虑将Telltale拆分为多个模块。</li><li>讨论了使用Web应用程序管理Telltale的测试和部署，以及研究使用其他测试框架或工具替代Telltale的部分功能。</li><li>探索了与其他社区合作，共享测试资源和经验。</li></ul><p>会议决定的事项包括：</p><ul><li>使用OVH实例搭建测试环境。</li><li>使用Jenkins进行测试任务调度。</li><li>创建特定测试套件。</li><li>更新Telltale测试套件，提高测试覆盖率。</li><li>探索使用分支或标签管理Telltale版本。</li><li>引入更智能的调度器，优化测试资源分配。</li><li>考虑将Telltale拆分为多个模块。</li><li>探索使用Web应用程序管理Telltale的测试和部署。</li><li>研究使用其他测试框架或工具替代Telltale的部分功能。</li><li>探索与其他社区合作，共享测试资源和经验。</li></ul><p>后续行动计划包括：</p><ul><li>Zack将继续开发libcloud后端，以便在OpenStack中创建临时的Telltale部署。</li><li>Mike将尝试运行Telltale测试套件，并查看其是否能够正常运行。</li><li>Greg将整理会议中讨论的所有想法，并将其记录在etherpad中。</li><li>所有参会人员将继续探讨Telltale测试框架的改进方案。</li></ul><p>本次会议内容涵盖了Ceph测试框架的改进，测试环境搭建，测试流程优化，开发模式探索等多个方面，对于Ceph社区的测试工作具有重要意义。</p>",7)])])}const d=e(_,[["render",p]]);export{c as __pageData,d as default};
